// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        // Keep amount positive and within a sane bound so Put/Collect can succeed
        amount = bound(amount, 1, 1 ether);
        // Align unlockTime with a timestamp we will set
        unlockTime = bound(unlockTime, 1, block.timestamp + 365 days);

        address actor = makeAddr("actor");
        vm.deal(actor, amount);

        // Establish the unlock time via Put, then warp exactly to the boundary
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Move to the exact unlock time so the reference rejects Collect
        vm.warp(unlockTime);

        uint256 balanceBefore = address(c).balance;

        // Attempt a boundary Collect; it will either succeed or silently return
        vm.prank(actor);
        c.Collect(amount);

        uint256 balanceAfter = address(c).balance;

        // General rule: at exactly the unlock timestamp, the reference must NOT
        // release funds (balance unchanged), while the mutant does release them.
        assertTrue(balanceAfter == balanceBefore);
    }
}
